from pathlib import Path
from playwright.sync_api import sync_playwright, expect
out=Path('test-results/personal-computer');out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(headless=True)
 context=b.new_context(viewport={'width':1440,'height':1000},permissions=['clipboard-read','clipboard-write'])
 page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto('http://127.0.0.1:5173',wait_until='networkidle')
 expect(page.locator('.computer-canvas canvas')).to_be_visible()
 expect(page.get_by_text('SYSTEM READY. CURIOSITY WELCOME.',exact=True)).to_be_visible()
 page.wait_for_timeout(300);page.screenshot(path=str(out/'hero-final.png'))
 before=page.locator('.computer-canvas').get_attribute('data-scene-progress')
 page.evaluate('window.scrollTo(0,1350)');page.wait_for_timeout(400)
 assert float(page.locator('.computer-canvas').get_attribute('data-scene-progress'))>float(before)
 page.screenshot(path=str(out/'tunnel-final.png'))
 page.get_by_role('button',name='Projects',exact=True).first.click();page.wait_for_timeout(900)
 expect(page.get_by_role('article',name='Projects window')).to_be_visible()
 page.get_by_role('button',name='AI',exact=True).click();expect(page.locator('.project-file')).to_have_count(2)
 page.get_by_role('button',name='Web',exact=True).click();expect(page.locator('.project-file')).to_have_count(1)
 page.get_by_role('button',name='Open Personal Computer project').click();expect(page.get_by_role('dialog')).to_be_visible()
 assert page.url.endswith('#project-personal-computer')
 page.keyboard.press('Escape');expect(page.get_by_role('dialog')).to_have_count(0);expect(page.get_by_role('button',name='Open Personal Computer project')).to_be_focused()
 page.get_by_role('button',name='All',exact=True).click()
 bar=page.locator('.window-titlebar').bounding_box();page.mouse.move(bar['x']+100,bar['y']+20);page.mouse.down();page.mouse.move(bar['x']+150,bar['y']+50);page.mouse.up()
 assert 'translate(50px,30px)' in page.locator('.desktop-window').get_attribute('style')
 page.get_by_role('button',name='Center window',exact=True).click();assert 'translate(0px,0px)' in page.locator('.desktop-window').get_attribute('style')
 page.get_by_role('button',name='Maximize window',exact=True).click();expect(page.locator('.desktop-shell')).to_have_class('desktop-shell window-maximized')
 page.get_by_role('button',name='Restore window',exact=True).click()
 page.get_by_role('button',name='Minimize window',exact=True).click();expect(page.locator('.desktop-window')).to_have_count(0)
 page.get_by_role('button',name='Switch to About me',exact=True).click();expect(page.get_by_role('article',name='About me window')).to_be_visible()
 page.get_by_role('button',name='Close window',exact=True).click();page.get_by_role('button',name='Start',exact=True).click();page.get_by_role('navigation',name='Start menu').get_by_role('button',name='Skills',exact=True).click()
 page.locator('.pc-skill-list summary').first.click();expect(page.locator('.pc-skill-list details').first).to_have_attribute('open','')
 page.get_by_role('button',name='Switch to Contact',exact=True).click();page.get_by_role('button',name='Copy email',exact=True).click();expect(page.get_by_role('button',name='Email copied')).to_be_visible()
 page.get_by_role('button',name='Switch to Resume',exact=True).click();page.evaluate('window.print=()=>window.printed=true');page.get_by_role('button',name='Print / Save PDF',exact=True).click();assert page.evaluate('window.printed')
 page.emulate_media(media='print');expect(page.locator('.pc-print-only')).to_be_visible();page.emulate_media(media='screen')
 page.get_by_role('button',name='Switch to Quality Lab',exact=True).click()
 lab=page.frame_locator('iframe[title="Portfolio Quality Lab worksheet"]');expect(lab.locator('.lab-exercise')).to_have_count(13)
 lab.get_by_label('Your name / batch').fill('Worksheet browser check')
 lab.get_by_label('Primary audience',exact=True).select_option('Someone else');lab.get_by_label('Describe your audience').fill('Future collaborators')
 with page.expect_download() as info:lab.get_by_role('button',name='Export answers',exact=True).click()
 info.value.save_as(str(out/'worksheet-answers.json'))
 page.get_by_role('button',name='Switch to About me',exact=True).click();page.get_by_role('button',name='Switch to Quality Lab',exact=True).click()
 expect(lab.get_by_label('Your name / batch')).to_have_value('Worksheet browser check')
 page.get_by_role('button',name='Motion full',exact=True).click();expect(page.locator('html')).to_have_attribute('data-motion','reduced')
 page.reload(wait_until='networkidle');expect(page.locator('html')).to_have_attribute('data-motion','reduced')
 for width in [320,390,768,1440]:
  page.set_viewport_size({'width':width,'height':844});page.wait_for_timeout(180)
  assert page.evaluate('document.documentElement.scrollWidth<=innerWidth'),f'overflow {width}'
 page.set_viewport_size({'width':390,'height':844});page.get_by_role('button',name='Switch to About me',exact=True).click();page.screenshot(path=str(out/'mobile-desktop.png'))
 page.get_by_role('link',name='VAIBHAV PERSONAL COMPUTER / V.01',exact=True).click();page.wait_for_timeout(200);page.screenshot(path=str(out/'mobile-final.png'))
 isolated=b.new_context(reduced_motion='reduce');ip=isolated.new_page();ip.goto('http://127.0.0.1:5173/quality-lab',wait_until='networkidle');expect(ip.get_by_label('Your name / batch')).to_have_value('')
 response=isolated.request.get('http://127.0.0.1:5173/documents/portfolio-quality-lab.pdf');assert response.status==200 and response.body().startswith(b'%PDF')
 ip.goto('http://127.0.0.1:5173/#project-personal-computer',wait_until='networkidle');expect(ip.get_by_role('dialog')).to_be_visible();expect(ip.locator('html')).to_have_attribute('data-motion','reduced');isolated.close()
 fallback=b.new_context();fp=fallback.new_page();fp.add_init_script("const original=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...args){return type==='webgl2'||type==='webgl'?null:original.call(this,type,...args)}")
 fp.goto('http://127.0.0.1:5173',wait_until='networkidle');expect(fp.locator('.pc-fallback')).to_be_visible();fp.get_by_role('button',name='Open desktop',exact=False).click();expect(fp.locator('.desktop-window')).to_be_visible();fallback.close()
 assert errors==[],errors
 print('PASS: WebGL scene and scroll progress, project filters/dialog/focus/deep links, window drag/center/maximize/minimize/close/start/taskbar, skills, clipboard, print, all 13 embedded worksheet exercises, persistence/export/context isolation, saved/OS reduced motion, 4 widths, PDF, no-WebGL fallback; no runtime errors.')
 b.close()
